    """Apply the observed nested rectangular trace independently in each panel."""
    h, w = len(grid), len(grid[0])
    sr = next((r for r in range(h) if all(v == 3 for v in grid[r])), None)
    sc = next((c for c in range(w) if all(grid[r][c] == 3 for r in range(h))), None)
    if sr is None or sc is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
