        for c0, c1 in ((0, sc-1), (sc+1, w-1)):
            # The demos show nested, alternating open rectangular rails.
            # Build inward successive rectangles, opening the side that
            # faces the next rail to create one continuous spiral.
            top, bot, left, right = r0, r1, c0, c1
            k = 0
            while top <= bot and left <= right:
                if k % 2 == 0:
                    for c in range(left, right+1): out[top][c] = 4
                    for r in range(top, bot+1): out[r][left] = 4
                    if bot > top:
                        for c in range(left+1, right+1): out[bot][c] = 4
                    if right > left:
                        for r in range(top+1, bot): out[r][right] = 4
                else:
                    for c in range(left, right+1): out[bot][c] = 4
                    for r in range(top, bot+1): out[r][right] = 4
                top += 2; bot -= 2; left += 2; right -= 2; k += 1
    return out
