    """Generate the nested winding trace pattern within each separator panel."""
    h, w = len(grid), len(grid[0])
    rs = [r for r in range(h) if all(x == 3 for x in grid[r])]
    cs = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    if not rs or not cs:
        return [row[:] for row in grid]
    rsep, csep = rs[0], cs[0]
    out = [row[:] for row in grid]
    for r0, r1 in ((0, rsep-1), (rsep+1, h-1)):
        for c0, c1 in ((0, csep-1), (csep+1, w-1)):
            ph, pw = r1-r0+1, c1-c0+1
            # Replicate the demonstrated winding bands: alternating nested
            # U/ C-shaped rails, with gaps defining the next inner turn.
            for level in range((min(ph,pw)+1)//2):
                t,b,l,r = r0+level, r1-level, c0+level, c1-level
                if t>b or l>r: break
                # Each successive turn alternates direction. Rails are
                # continuous around three sides and leave the entry gap.
                if level % 2 == 0:
                    for c in range(l,r+1): out[t][c]=4
